{
  "name": "SPD1000系列可编程直流电源",
  "name_en": "SPD1000 Series Programmable DC Power Supply",
  "manufacturer": "Siglent",
  "description": "用于实验室供电的可编程直流电源，可设置电压和电流、切换输出、启用远端感测，并测量输出电压、电流和功率，适合为电子电路与器件测试提供稳定电源。",
  "description_en": "A programmable DC power supply for laboratory use. It can set voltage and current, switch output on or off, enable remote sensing, and measure output voltage, current, and power, making it suitable for powering electronic circuits and device tests.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化设备并选择通道1。",
      "description_en": "Initialize the device and select channel 1."
    },
    {
      "action_name": "auto-lock_commands",
      "description": "锁定或解锁命令控制状态。",
      "description_en": "Lock or unlock the command control state."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量输出电流。",
      "description_en": "Measure the output current."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量输出功率。",
      "description_en": "Measure the output power."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量输出电压。",
      "description_en": "Measure the output voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "设置远端感测状态。",
      "description_en": "Set remote sense state."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置电流设定值。",
      "description_en": "Set current setpoint."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置电压设定值。",
      "description_en": "Set voltage setpoint."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭输出。",
      "description_en": "Turn the output on or off."
    },
    {
      "action_name": "auto-get_current",
      "description": "获取电流设定值。",
      "description_en": "Get current setpoint."
    },
    {
      "action_name": "auto-get_voltage",
      "description": "获取电压设定值。",
      "description_en": "Get voltage setpoint."
    },
    {
      "action_name": "auto-get_output",
      "description": "获取输出状态。",
      "description_en": "Get output state."
    },
    {
      "action_name": "auto-get_remote_sense",
      "description": "获取远端感测状态。",
      "description_en": "Get remote sense state."
    }
  ],
  "tag_hints": [
    "programmable DC power supply",
    "voltage sourcing",
    "current limiting",
    "output enable control",
    "remote sense",
    "electrical measurement",
    "bench power supply"
  ]
}

